#!/bin/zsh
# Xcode Cloud: generate the native iOS project after the clone.
#
# mobile/ios is generated by Expo (Continuous Native Generation) and not
# committed, so this does what EAS does before a build: install JS deps,
# `expo prebuild` the production variant, `pod install`. The committed
# workspace beside this folder (Transit.xcworkspace) points at ../ios.
#
# Build numbers: CFBundleVersion is the build's UTC time, YYMMDDHHMM (e.g.
# 2611242005), so every build - a Rebuild too, which reuses CI_BUILD_NUMBER -
# is higher than the last upload, and above EAS's numbers (124 when this was
# set up). Set XCC_BUILD_NUMBER in the workflow's environment to force one.
set -euo pipefail

MOBILE="$CI_PRIMARY_REPOSITORY_PATH/mobile"

echo "== Tools"
export HOMEBREW_NO_AUTO_UPDATE=1 HOMEBREW_NO_INSTALL_CLEANUP=1 HOMEBREW_NO_INSTALLED_DEPENDENTS_CHECK=1
command -v node >/dev/null && node --version | grep -q '^v24\.' || brew install node@24
[[ -d "$(brew --prefix node@24 2>/dev/null)/bin" ]] && export PATH="$(brew --prefix node@24)/bin:$PATH"
command -v pod >/dev/null || brew install cocoapods
node --version
pod --version

echo "== JS dependencies"
cd "$MOBILE"
npm ci --no-audit --no-fund

echo "== Expo prebuild (production)"
export APP_VARIANT=production
npx expo prebuild --platform ios --no-install

echo "== CocoaPods"
cd "$MOBILE/ios"
# Script phases (Bundle React Native code, Expo config) find node through this.
echo "export NODE_BINARY=$(command -v node)" > .xcode.env.local
pod install

echo "== Build number"
BUILD=${XCC_BUILD_NUMBER:-$(date -u +%y%m%d%H%M)}
sed -i '' -E "s/CURRENT_PROJECT_VERSION = [^;]+;/CURRENT_PROJECT_VERSION = $BUILD;/g" Transit.xcodeproj/project.pbxproj
/usr/libexec/PlistBuddy -c "Set :CFBundleVersion $BUILD" Transit/Info.plist
echo "CFBundleVersion $BUILD"
